pub(super) fn with_state<S2>(self, state: S) -> PathRouter<S2, B> {
    let routes = self
        .routes
        .into_iter()
        .map(|(id, endpoint)| {
            let endpoint: Endpoint<S2, B> = match endpoint {
                Endpoint::MethodRouter(method_router) => {
                    Endpoint::MethodRouter(method_router.with_state(state.clone()))
                }
                Endpoint::Route(route) => Endpoint::Route(route),
            };
            (id, endpoint)
        })
        .collect();

    PathRouter {
        routes,
        node: self.node,
        prev_route_id: self.prev_route_id,
    }
}

pub(super) fn call_with_state(
    &mut self,
    mut req: Request<B>,
    state: S,
) -> Result<RouteFuture<B, Infallible>, (Request<B>, S)> {
    #[cfg(feature = "original-uri")]
    {
        use crate::extract::OriginalUri;

        if req.extensions().get::<OriginalUri>().is_none() {
            let original_uri = OriginalUri(req.uri().clone());
            req.extensions_mut().insert(original_uri);
        }
    }

    let path = req.uri().path().to_owned();

    match self.node.at(&path) {
        Ok(match_) => {
            let id = *match_.value;

            #[cfg(feature = "matched-path")]
            {
                use crate::extract::matched_path::{MatchedNestedPath, MatchedPath};

                let extensions = req.extensions_mut();
                if let Some(matched_path) = self.node.route_id_to_path.get(&id) {
                    let matched_path = if let Some(previous) = extensions
                        .get::<MatchedPath>()
                        .map(|matched_path| matched_path.as_str())
                        .or_else(|| {
                            extensions
                                .get::<MatchedNestedPath>()
                                .map(|nested| nested.0.as_ref())
                        })
                    {
                        let previous = if let Some(stripped) =
                            previous.strip_suffix(super::NEST_TAIL_PARAM_CAPTURE)
                        {
                            stripped
                        } else {
                            previous
                        };

                        format!("{previous}{matched_path}").into()
                    } else {
                        Arc::clone(matched_path)
                    };

                    if matched_path.ends_with(super::NEST_TAIL_PARAM_CAPTURE) {
                        extensions.insert(MatchedNestedPath(matched_path));
                        debug_assert!(matches!(extensions.remove::<MatchedPath>(), None));
                    } else {
                        extensions.insert(MatchedPath(matched_path));
                        extensions.remove::<MatchedNestedPath>();
                    }
                } else {
                    #[cfg(debug_assertions)]
                    panic!("should always have a matched path for a route id");
                }
            }

            let extensions = req.extensions_mut();
            if let Some(url_params::UrlParams::InvalidUtf8InPathParam { .. }) =
                extensions.get::<url_params::UrlParams>()
            {
                // Invalid UTF-8 was already recorded for this request.
            } else {
                let mut decoded_params = Vec::new();
                let mut invalid_utf8_key = None;

                for (key, value) in match_.params.iter() {
                    if key.starts_with(NEST_TAIL_PARAM) {
                        continue;
                    }
                    if key.starts_with(FALLBACK_PARAM) {
                        continue;
                    }

                    match url_params::try_decode_path_param(key, value) {
                        Ok(pair) => decoded_params.push(pair),
                        Err(key) => {
                            invalid_utf8_key = Some(key);
                            break;
                        }
                    }
                }

                match (
                    extensions.get_mut::<url_params::UrlParams>(),
                    invalid_utf8_key,
                ) {
                    (Some(url_params::UrlParams::InvalidUtf8InPathParam { .. }), _) => {
                        unreachable!(
                            "we check for this state earlier in this method"
                        )
                    }
                    (_, Some(invalid_key)) => {
                        extensions.insert(url_params::UrlParams::InvalidUtf8InPathParam {
                            key: invalid_key,
                        });
                    }
                    (Some(url_params::UrlParams::Params(current)), None) => {
                        current.extend(decoded_params);
                    }
                    (None, None) => {
                        extensions.insert(url_params::UrlParams::Params(decoded_params));
                    }
                }
            }

            let endpont = self
                .routes
                .get_mut(&id)
                .expect("no route for id. This is a bug in axum. Please file an issue");

            match endpont {
                Endpoint::MethodRouter(method_router) => {
                    Ok(method_router.call_with_state(req, state))
                }
                Endpoint::Route(route) => Ok(route.clone().call(req)),
            }
        }
        // explicitly handle all variants in case matchit adds
        // new ones we need to handle differently
        Err(MatchError::NotFound) => Err((req, state)),
        Err(MatchError::ExtraTrailingSlash) => Err((req, state)),
        Err(MatchError::MissingTrailingSlash) => Err((req, state)),
    }
}

pub(super) fn replace_endpoint(&mut self, path: &str, endpoint: Endpoint<S, B>) {
    match self.node.at(path) {
        Ok(match_) => {
            let id = *match_.value;
            self.routes.insert(id, endpoint);
        }
        Err(_) => self
            .route_endpoint(path, endpoint)
            .expect("path wasn't matched so endpoint shouldn't exist"),
    }
}

